import json, urllib.request, concurrent.futures
KEY="sk-rHFQK9bmRyGRTxeWw7RcGA"
URL="https://llm-gateway.galbot.com/v1/chat/completions"
def call(p):
    req=urllib.request.Request(URL, data=json.dumps(p).encode(),
        headers={"Authorization":"Bearer "+KEY,"Content-Type":"application/json"})
    try:
        with urllib.request.urlopen(req, timeout=120) as r: return json.load(r)
    except Exception as e:
        b=""
        try: b=e.read().decode()[:200]
        except Exception: pass
        return {"error":f"{e} {b}"}
def probe(m):
    r=call({"model":m,"messages":[{"role":"user","content":"Compute 17*23+11 step by step."}],"max_tokens":1500,"reasoning_effort":"high"})
    if "error" in r: return (m, r["error"][:120])
    msg=r["choices"][0]["message"]
    u=r.get("usage",{})
    return (m, r.get("model"), "reasoning="+str(bool(msg.get("reasoning_content"))), "rtok="+str((u.get("completion_tokens_details") or {}).get("reasoning_tokens")))
