import json, netrc, urllib.request, urllib.error, urllib.parse
from pathlib import Path

host = 'git.galbot.com'
values = []
try:
    auth = netrc.netrc().authenticators(host)
    if auth: values.append(auth[2])
except Exception:
    pass
p = Path.home() / '.git-credentials'
if p.exists():
    for line in p.read_text().splitlines():
        u = urllib.parse.urlsplit(line)
        if u.hostname == host and u.password:
            values.append(urllib.parse.unquote(u.password))

def api(route, method='GET', payload=None):
    for token in dict.fromkeys(values):
        req = urllib.request.Request(
            f'https://{host}/api/v4/{route}',
            data=json.dumps(payload).encode() if payload is not None else None,
            method=method,
            headers={'PRIVATE-TOKEN': token, 'Content-Type': 'application/json'}
        )
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return json.load(r)
        except urllib.error.HTTPError as e:
            if e.code == 401:
                continue
            print(route, e.code, e.read().decode(errors='replace')[:300])
            return None

for pid in [3213, 3215]:
    print("hooks", pid, api(f"projects/{pid}/hooks"))
    print("branches", pid, [b["name"] for b in (api(f"projects/{pid}/repository/branches") or [])])
